#include <iostream>
#include <string>
#include <fstream>
#include <omniORB4/CORBA.h>

#include "echo.hh" // Generated by the IDL compiler

int main(int argc, char* argv[]) {
    try {
        // Initialize the ORB.
        CORBA::ORB_var orb = CORBA::ORB_init(argc, argv);

        // Read the IOR from the file.
        std::ifstream ior_file("echo.ior");
        std::string ior_string;
        if (ior_file.is_open()) {
            std::getline(ior_file, ior_string);
            ior_file.close();
        } else {
            std::cerr << "Unable to open echo.ior file" << std::endl;
            return 1;
        }

        // Obtain the object reference from the IOR string.
        CORBA::Object_var obj = orb->string_to_object(ior_string.c_str());
        Echo_var echo_ref = Echo::_narrow(obj);

        if (CORBA::is_nil(echo_ref)) {
            std::cerr << "Invalid object reference." << std::endl;
            return 1;
        }

        // Invoke the echoString operation.
        const char* message = "Hello, CORBA!";
        CORBA::String_var result = echo_ref->echoString(message);
        std::cout << "Received from server: " << result.in() << std::endl;

        // Cleanup.
        orb->destroy();

    } catch (CORBA::Exception& ex) {
        std::cerr << "CORBA exception: " << ex._name() << std::endl;
        return 1;
    }

    return 0;
}
